buildscript {
    repositories {
        google()
        mavenCentral()
    }
    dependencies {
        classpath("com.android.tools.build:gradle:8.11.0")
        // 2.2.20 (was 1.9.25): the UnifiedPush connector pulls kotlin-stdlib
        // 2.3.0, whose metadata the 1.9.x compiler cannot read; 2.2.x reads
        // it while keeping the old `jvmTarget` DSL the vendored tauri
        // mobile gradle script still uses (KGP 2.3 hard-errors on it).
        // This file is autogenerated by `cargo tauri android init` —
        // re-apply the bump after regenerating.
        classpath("org.jetbrains.kotlin:kotlin-gradle-plugin:2.2.20")
    }
}

allprojects {
    repositories {
        google()
        mavenCentral()
    }
}

tasks.register("clean").configure {
    delete("build")
}

